# -*- coding: utf-8 -*-
import os, sqlite3, secrets, time
from datetime import datetime
from flask import Flask, request, redirect, session, send_from_directory, render_template_string, jsonify
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY', '3RITWO-change-this-secret-before-public-' + secrets.token_hex(16))
app.config['MAX_CONTENT_LENGTH'] = 250 * 1024 * 1024
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
MEDIA_DIR = os.path.join(BASE_DIR, 'media')
DB_PATH = os.path.join(BASE_DIR, 'music.db')
os.makedirs(MEDIA_DIR, exist_ok=True)
ADMIN_PASSWORD = os.environ.get('ADMIN_PASSWORD', 'Abolfazl')
ALLOWED = {'photo': {'jpg','jpeg','png','webp','gif'}, 'cover': {'jpg','jpeg','png','webp'}, 'audio': {'mp3','wav','ogg','m4a','aac','flac'}, 'video': {'mp4','webm','mov','m4v'}}

def db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con

def add_column(con, table, name, declaration):
    cols = [r['name'] for r in con.execute('PRAGMA table_info(' + table + ')').fetchall()]
    if name not in cols:
        con.execute('ALTER TABLE ' + table + ' ADD COLUMN ' + name + ' ' + declaration)

def init_db():
    with db() as con:
        con.execute('CREATE TABLE IF NOT EXISTS songs (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,artist TEXT NOT NULL,cover TEXT,audio TEXT,lyrics TEXT,video TEXT)')
        con.execute("CREATE TABLE IF NOT EXISTS photos (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,caption TEXT,filename TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)")
        con.execute("CREATE TABLE IF NOT EXISTS videos (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,caption TEXT,filename TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'video',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)")
        for col in ('plays INTEGER NOT NULL DEFAULT 0','views INTEGER NOT NULL DEFAULT 0','likes INTEGER NOT NULL DEFAULT 0'):
            add_column(con,'songs',col.split()[0],col.split(' ',1)[1])
        for col in ('views INTEGER NOT NULL DEFAULT 0','likes INTEGER NOT NULL DEFAULT 0'):
            add_column(con,'videos',col.split()[0],col.split(' ',1)[1])
        con.execute('CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY AUTOINCREMENT,song_id INTEGER NOT NULL,name TEXT NOT NULL,text TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')
        con.execute('CREATE TABLE IF NOT EXISTS song_likes (song_id INTEGER NOT NULL,visitor_id TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(song_id,visitor_id))')
        con.execute('CREATE TABLE IF NOT EXISTS photo_likes (photo_id INTEGER NOT NULL,visitor_id TEXT NOT NULL,PRIMARY KEY(photo_id,visitor_id))')
        con.execute('CREATE TABLE IF NOT EXISTS video_likes (video_id INTEGER NOT NULL,visitor_id TEXT NOT NULL,PRIMARY KEY(video_id,visitor_id))')
        con.execute('CREATE TABLE IF NOT EXISTS video_comments (id INTEGER PRIMARY KEY AUTOINCREMENT,video_id INTEGER NOT NULL,name TEXT NOT NULL,text TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')
init_db()

