@app.route('/api/videos/<int:video_id>/like', methods=['POST'])
def video_like(video_id):
    who=visitor_id()
    with db() as con:
        if not con.execute('SELECT 1 FROM videos WHERE id=?',(video_id,)).fetchone(): return jsonify(error='ویدئو پیدا نشد'),404
        old=con.execute('SELECT 1 FROM video_likes WHERE video_id=? AND visitor_id=?',(video_id,who)).fetchone()
        if old: con.execute('DELETE FROM video_likes WHERE video_id=? AND visitor_id=?',(video_id,who)); liked=False
        else: con.execute('INSERT OR IGNORE INTO video_likes(video_id,visitor_id) VALUES(?,?)',(video_id,who)); liked=True
        count=con.execute('SELECT COUNT(*) AS n FROM video_likes WHERE video_id=?',(video_id,)).fetchone()['n']
        con.execute('UPDATE videos SET likes=? WHERE id=?',(count,video_id))
    return jsonify(likes=count,liked=liked)

@app.route('/api/videos/<int:video_id>/comments', methods=['GET','POST'])
def video_comments(video_id):
    with db() as con:
        if not con.execute('SELECT 1 FROM videos WHERE id=?',(video_id,)).fetchone(): return jsonify(error='ویدئو پیدا نشد'),404
        if request.method=='POST':
            name=(request.form.get('name') or '').strip()[:35] or 'بیننده'
            text=(request.form.get('text') or '').strip()[:700]
            if not text:return jsonify(error='متن نظر خالی است'),400
            con.execute('INSERT INTO video_comments(video_id,name,text) VALUES(?,?,?)',(video_id,name,text))
        rows=con.execute('SELECT name,text,created_at FROM video_comments WHERE video_id=? ORDER BY id DESC LIMIT 100',(video_id,)).fetchall()
    return jsonify(comments=[dict(r) for r in rows])

@app.route('/admin',methods=['GET','POST'])
def admin():
    error=None
    if request.method=='POST':
        action=request.form.get('action','')
        if action=='login':
            if secrets.compare_digest(request.form.get('password',''),ADMIN_PASSWORD):
                session.clear();session['admin']=True;return redirect('/admin')
            error='رمز عبور اشتباه است.'
            return render_template_string(ADMIN,logged=False,songs=[],photos=[],videos=[],error=error),401
        if not is_admin(): return 'دسترسی غیرمجاز',403
        try:
            if action=='add_song':
                title=request.form.get('title','').strip();artist=request.form.get('artist','3RITWO').strip()
                if not title or not artist: return render_template_string(ADMIN,logged=True,songs=[],photos=[],videos=[],error='عنوان و نام هنرمند الزامی است.'),400
                cover=save_upload('cover','cover');audio=save_upload('audio','audio');lyrics=request.form.get('lyrics','').strip()
                if not audio: return render_template_string(ADMIN,logged=True,songs=[],photos=[],videos=[],error='فایل صوتی را انتخاب کن.'),400
                with db() as con: con.execute('INSERT INTO songs(title,artist,cover,audio,lyrics,video) VALUES(?,?,?,?,?,NULL)',(title,artist,cover,audio,lyrics))
            elif action=='add_photo':
                title=request.form.get('title','').strip();caption=request.form.get('caption','').strip();filename=save_upload('photo','photo')
                if not title or not filename: return render_template_string(ADMIN,logged=True,songs=[],photos=[],videos=[],error='عنوان و عکس الزامی است.'),400
                with db() as con: con.execute('INSERT INTO photos(title,caption,filename) VALUES(?,?,?)',(title,caption,filename))
            elif action=='add_video':
                title=request.form.get('title','').strip();caption=request.form.get('caption','').strip();kind=request.form.get('kind','video')
                if kind not in ('video','freestyle'):kind='video'
                filename=save_upload('video','video')
                if not title or not filename:return render_template_string(ADMIN,logged=True,songs=[],photos=[],videos=[],error='عنوان و فایل ویدئو الزامی است.'),400
                with db() as con:con.execute('INSERT INTO videos(title,caption,filename,kind) VALUES(?,?,?,?)',(title,caption,filename,kind))
            elif action=='delete_song':
                with db() as con:
                    row=con.execute('SELECT cover,audio,video FROM songs WHERE id=?',(request.form.get('id'),)).fetchone();con.execute('DELETE FROM songs WHERE id=?',(request.form.get('id'),));con.execute('DELETE FROM comments WHERE song_id=?',(request.form.get('id'),));con.execute('DELETE FROM song_likes WHERE song_id=?',(request.form.get('id'),))
                if row:
                    for f in row:remove_file(f)
            elif action=='delete_photo':
                with db() as con:row=con.execute('SELECT filename FROM photos WHERE id=?',(request.form.get('id'),)).fetchone();con.execute('DELETE FROM photos WHERE id=?',(request.form.get('id'),))
                if row:remove_file(row['filename'])
            elif action=='delete_video':
                with db() as con:row=con.execute('SELECT filename FROM videos WHERE id=?',(request.form.get('id'),)).fetchone();con.execute('DELETE FROM videos WHERE id=?',(request.form.get('id'),))
                if row:remove_file(row['filename'])
        except ValueError as e:
            error=str(e)
        if error:
            with db() as con:
                songs=con.execute('SELECT * FROM songs ORDER BY id DESC').fetchall();photos=con.execute('SELECT * FROM photos ORDER BY id DESC').fetchall();videos=con.execute('SELECT * FROM videos ORDER BY id DESC').fetchall()
            return render_template_string(ADMIN,logged=True,songs=songs,photos=photos,videos=videos,error=error),400
        return redirect('/admin')
    songs=photos=videos=[]
    if is_admin():
        with db() as con:
            songs=con.execute('SELECT * FROM songs ORDER BY id DESC').fetchall();photos=con.execute('SELECT * FROM photos ORDER BY id DESC').fetchall();videos=con.execute('SELECT * FROM videos ORDER BY id DESC').fetchall()
    return render_template_string(ADMIN,logged=is_admin(),songs=songs,photos=photos,videos=videos,error=error)

